using namespace IQM::HDRVDP3;namespace fs=std::filesystem;
std::vector<double> readRow(const fs::path&p,unsigned w){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f||f.tellg()!=std::streamoff(w*w*8))throw std::runtime_error("Reference shape "+p.string());std::vector<double> v(w*w),r(w*w);f.seekg(0);f.read(reinterpret_cast<char*>(v.data()),v.size()*8);for(unsigned y=0;y<w;++y)for(unsigned x=0;x<w;++x)r[y*w+x]=v[x*w+y];return r;}
int main(int argc,char**argv){try{if(argc!=4)throw std::invalid_argument("Usage: v9-runtime cpu-root fresh-output");fs::path runtime=argv[1],cpu=argv[2],out=argv[3];if(fs::exists(out)||!fs::create_directories(out))throw std::invalid_argument("Fresh output");auto model=load_srgb_quality96_runtime_double(runtime,"oled");IQM::Bin::VulkanInstance instance(true,"NVIDIA",true);SRGBQuality96GPUDouble gpu(*instance.physicalDevice(),*instance.device(),*instance.queue(),instance.queueFamilyIndex,true,model.shaders,model.projection,model.mutual,model.neighbor,model.pyramid,model.comparison,model.jnd,model.csf,model.quality);size_t words=0,errors=0;std::ofstream log(out/"comparisons.tsv");auto compare=[&](const std::vector<double>&a,const std::vector<double>&b,const std::string& name){if(a.size()!=b.size())throw std::runtime_error("Shape");size_t bad=0;for(size_t i=0;i<a.size();++i)if(std::bit_cast<uint64_t>(a[i])!=std::bit_cast<uint64_t>(b[i])){if(!bad)std::cout<<name<<" first mismatch "<<i<<'\n';++bad;}errors+=bad;words+=a.size();log<<name<<'\t'<<bad<<'/'<<a.size()<<'\n';};const unsigned widths[]{96,96,48,24,12};double p=quality_mask_parameters_double()[0];
 for(std::string native:{"native","native_ramps","native_identity_v2"})for(std::string display:{"led-lcd-srgb","led-lcd-wcg","oled"})for(unsigned b=0;b<5;++b){unsigned w=widths[b];const auto prefix=(cpu/native/(display+"_quality_band"+std::to_string(b+1))).string();auto diff=readRow(prefix+"_band_diff.f64",w),self=readRow(prefix+"_self.f64",w),neighbor=readRow(prefix+"_neighbor.f64",w),noise=readRow(prefix+"_noise.f64",w),comparison=readRow(prefix+"_comparison.f64",w);std::vector<double> denominator;double pooling=0;auto result=gpu.quality(diff,self,neighbor,noise,comparison,w,w,&denominator,&pooling);const auto name=native+"_"+display+"_band"+std::to_string(b+1);for(auto item:{std::pair{"mask_noise",&result.mask_noise},std::pair{"excitation",&result.excitation},std::pair{"difference",&result.difference},std::pair{"psychometric",&result.psychometric},std::pair{"masked",&result.masked}}){auto expected=readRow(prefix+"_"+item.first+".f64",w);std::ofstream f(out/(name+"_"+item.first+".f64"),std::ios::binary);f.write(reinterpret_cast<const char*>(item.second->data()),item.second->size()*8);compare(*item.second,expected,item.first);}
 auto mask=readRow(prefix+"_mask_noise.f64",w);std::vector<double> expectedDenominator(mask.size());for(size_t i=0;i<mask.size();++i)expectedDenominator[i]=std::sqrt(std::pow(noise[i],2*p)+mask[i]*mask[i]);for(auto item:{std::pair{"denominator",&denominator},std::pair{"denominator_expected",&expectedDenominator}}){std::ofstream f(out/(name+"_"+item.first+".f64"),std::ios::binary);f.write(reinterpret_cast<const char*>(item.second->data()),item.second->size()*8);}compare(denominator,expectedDenominator,"sqrt denominator");auto expectedMasked=readRow(prefix+"_masked.f64",w);double expectedPool=0;for(unsigned x=0;x<w;++x)for(unsigned y=0;y<w;++y)expectedPool+=std::pow(std::abs(expectedMasked[y*w+x]),.8)/double(w*w);compare({pooling},{expectedPool},"raw pooling");std::ofstream raw(out/(name+"_pooling.f64"),std::ios::binary);raw.write(reinterpret_cast<const char*>(&pooling),8);compare({result.error},readRow(prefix+"_error.f64",1),"error");}
 size_t nativeWords=words;for(unsigned seed=0;seed<5;++seed)for(unsigned w:widths){size_t n=size_t(w)*w;std::vector<double> diff(n),self(n),neighbor(n),noise(n,.1),comparison(n,1.);for(size_t i=0;i<n;++i){if(seed==1){diff[i]=(i%2?-1.:1.)*double(i%17)*.01;self[i]=double(i%31)*.001;neighbor[i]=double(i%23)*.01;noise[i]=.01+double(i%19)*.003;comparison[i]=i%4==0?-0.:i%4==1?-.02:i%4==2?1.:1.05;}else if(seed==2){diff[i]=i%2?-1.:.5;self[i]=.05;neighbor[i]=.1;noise[i]=std::numeric_limits<double>::infinity();comparison[i]=i%3==0?-0.:1.;}else if(seed==3){diff[i]=(i==0||i==n/2)?1.:0.;noise[i]=1e-3;}else if(seed==4){diff[i]=i%2?-1e-50:1e-50;self[i]=1e-10;neighbor[i]=1e-12;noise[i]=.5;comparison[i]=i%3==0?-0.:i%3==1?-1e-8:1e-8;}}
 std::vector<double> denominator;double pooling=0;auto a=gpu.quality(diff,self,neighbor,noise,comparison,w,w,&denominator,&pooling),e=evaluate_quality_band_double(diff,self,neighbor,noise,comparison,w,w);for(auto pair:{std::pair{&a.mask_noise,&e.mask_noise},std::pair{&a.excitation,&e.excitation},std::pair{&a.difference,&e.difference},std::pair{&a.psychometric,&e.psychometric},std::pair{&a.masked,&e.masked}})compare(*pair.first,*pair.second,"control map");std::vector<double> expected(n);for(size_t i=0;i<n;++i)expected[i]=std::sqrt(std::pow(noise[i],2*p)+e.mask_noise[i]*e.mask_noise[i]);compare(denominator,expected,"control sqrt");double expectedPool=0;for(unsigned x=0;x<w;++x)for(unsigned y=0;y<w;++y)expectedPool+=std::pow(std::abs(e.masked[y*w+x]),.8)/double(n);compare({pooling},{expectedPool},"control raw pooling");compare({a.error},{e.error},"control error");}
 unsigned rejected=0;auto reject=[&](auto action){try{action();}catch(const std::exception&){++rejected;return;}throw std::runtime_error("Invalid quality input accepted");};std::vector<double> d(9216,0.),s(9216,0.),neighbor=s,noise(9216,1.),comparison=noise;reject([&]{gpu.quality(d,s,neighbor,noise,comparison,20,20);});reject([&]{gpu.quality(d,s,neighbor,noise,comparison,96,48);});reject([&]{gpu.quality({},s,neighbor,noise,comparison,96,96);});s[0]=-1.;reject([&]{gpu.quality(d,s,neighbor,noise,comparison,96,96);});s[0]=0.;neighbor[0]=-1.;reject([&]{gpu.quality(d,s,neighbor,noise,comparison,96,96);});neighbor[0]=0.;for(double v:{0.,std::numeric_limits<double>::quiet_NaN(),-std::numeric_limits<double>::infinity()}){noise[0]=v;reject([&]{gpu.quality(d,s,neighbor,noise,comparison,96,96);});}noise[0]=1.;comparison[0]=std::numeric_limits<double>::infinity();reject([&]{gpu.quality(d,s,neighbor,noise,comparison,96,96);});comparison[0]=1.;d[0]=std::numeric_limits<double>::quiet_NaN();reject([&]{gpu.quality(d,s,neighbor,noise,comparison,96,96);});
 std::cout<<errors<<" bit errors /"<<words<<" hybrid quality words\n";std::ofstream(out/"results.txt")<<errors<<" bit errors /"<<words<<" hybrid quality words\n";if(errors)return 2;std::ofstream(out/"PASS.txt")<<nativeWords<<" native/derived Double quality words exact;"<<words-nativeWords<<" control words exact;"<<rejected<<" rejection checks\n";return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
